import { Api } from './base/Api';
export class AppApi extends Api {
    constructor(cdn, baseUrl, options) {
        super(baseUrl, options);
        this.cdn = cdn;
    }
    getProductList() {
        return this.get('/product').then((data) => data.items.map((card) => (Object.assign(Object.assign({}, card), { image: this.cdn + card.image }))));
    }
    getProductItem(id) {
        return this.get(`/product/${id}`).then((card) => (Object.assign(Object.assign({}, card), { image: this.cdn + card.image })));
    }
    ;
    orderProducts(order) {
        return this.post('/order', order).then((data) => data);
    }
    ;
}
