// Базовый класс для работы с HTML элементами
export class Component {
    constructor(container) {
        this.container = container;
    }
    setText(element, value) {
        if (element) {
            element.textContent = String(value);
        }
    }
    setColorCategory(element, category) {
        element.classList.toggle(category);
    }
    setImage(element, src, alt) {
        if (element) {
            element.src = src;
            if (alt) {
                element.alt = alt;
            }
        }
    }
    render(data) {
        Object.assign(this, data !== null && data !== void 0 ? data : {});
        return this.container;
    }
}
export class View extends Component {
    constructor(events, container) {
        super(container);
        this.events = events;
    }
}
